// ---- lootable helper
async function lootable(name, marker, size, desc, entries){
  const actor = await tpl.clone({name, folder:FOLDER},{save:true});
  const docs=[];
  for (const [id,q] of entries){ const uuid=`Compendium.dnd-players-handbook.equipment.Item.${id}`; const o=(await fromUuid(uuid)).toObject(); delete o._id; o.system.quantity=q; o._stats=foundry.utils.mergeObject(o._stats??{},{compendiumSource:uuid}); docs.push(o); }
  if (docs.length) await actor.createEmbeddedDocuments('Item', docs);
  const imgs={closedImage:ICON,openedImage:ICON,lockedImage:ICON,emptyImage:ICON,description:desc,closed:true,locked:false,deleteWhenEmpty:false,distance:1};
  const merged=foundry.utils.mergeObject(actor.getFlag('item-piles','data')??{},imgs);
  await actor.update({img:ICON,"flags.item-piles.data":merged,"prototypeToken.name":name,"prototypeToken.width":size,"prototypeToken.height":size,"prototypeToken.texture.src":ICON,"prototypeToken.flags.item-piles.data":merged});
  const c=ctr(marker);
  const td=await actor.getTokenDocument({x:c.x-size*g/2,y:c.y-size*g/2});
  const [tok]=await scene.createEmbeddedDocuments('Token',[td.toObject()]);
  await tok.update({"texture.src":ICON,"flags.item-piles.data":merged});
  return {actor,tok};
}
