for (const e of reg) {
  if (derivedNs.test(e.id) && e.secret===true) out.derivedSecret.push(e.id);
  if (isSecret(e) && e.parent) { const p = byId.get(e.parent); if (!p) out.dangling.push(e.id); else if (!isSecret(p)) out.visibleParentOfSecret.push(`${e.id}<${p.id}`); }
  if (e.whenKnown==='auto'||e.whenCarried==='auto') out.autoHelp.push(e.id);
  if (e.whenKnown==='advantage'||e.whenCarried==='advantage') out.advHelp.push(e.id);
  if (e.hold===true) out.holds++;
}
// authored attribute ids on actors with no registry entry
const unreg = new Set();
for (const a of game.actors) for (const id of (a.getFlag(M,'attributes')??[])) if (typeof id==='string' && !byId.has(id) && !derivedNs.test(id)) unreg.add(id);
out.unregisteredAuthored = [...unreg].slice(0,20);
