let checked = 0, diffs = [];
for (const subject of game.actors) {
  const carried = ties.attributes.of(subject).map(x => typeof x === "string" ? x : x.id);
  // old preview loop
  const rungs = [], ladderOf = new Map();
  for (const id of carried) {
    if (!regById.get(id)?.secret) continue;
    const ladder = kc.identificationLadder(id, reg).filter(r => carried.includes(r));
    ladder.forEach((r, i) => { if (!ladderOf.has(r)) ladderOf.set(r, ladder[i - 1] ?? null); if (!rungs.includes(r)) rungs.push(r); });
  }
  const old = [
    ...rungs.map(id => `ident|${id}|${ladderOf.get(id)}`),
    ...carried.flatMap(id => kc.rollableLore(regById.get(id)?.lore).map(r => `attr|${id}|${r.id}`)),
    ...kc.rollableLore(subject.getFlag("pentaryn-ties", "lore")).map(r => `lore|${r.id}`)
  ];
  const kind = study.kindActor(subject);
  const nu = kc.factOrder({ subjectId: subject.id, kindId: kind?.id ?? null, carried, registry: reg, lore: subject.getFlag("pentaryn-ties", "lore") })
    .filter(x => x.group !== "kind")
    .map(x => x.ns === "ident" ? `ident|${x.attrId}|${x.parentId}` : x.ns === "attr" ? `attr|${x.attrId}|${x.factId}` : `lore|${x.factId}`);
  checked++;
  if (JSON.stringify(old) !== JSON.stringify(nu)) diffs.push({ name: subject.name, old, nu });
}
return { world: game.world.id, checked, withFacts: null, diffs: diffs.slice(0, 5), ndiff: diffs.length };

