return {edge:{sight:e?.sight, threshold:e?.threshold}, visibleLitArea: area(inter.points), pct: Math.round(100*area(inter.points)/area(full.points)), centerBlockedBy: col.flatMap(v=>[...v.edges].map(x=>x.object?.id))};

