const comp = (sid, px, py) => {
  const A = game.scenes.get(sid), G = A.grid.size, X0 = A.dimensions.sceneX, Y0 = A.dimensions.sceneY;
  const COLS = Math.round(A.width/G), ROWS = Math.round(A.height/G);
  const walls = A.walls.filter(w => w.move > 0 && !w.door).map(w => w.c);
  const ccw = (a,b,c) => (c[1]-a[1])*(b[0]-a[0]) > (b[1]-a[1])*(c[0]-a[0]);
  const cross = (p1,p2,p3,p4) => (ccw(p1,p3,p4) !== ccw(p2,p3,p4)) && (ccw(p1,p2,p3) !== ccw(p1,p2,p4));
  const centre = (i,j) => [X0 + i*G + G/2, Y0 + j*G + G/2];
  const blocked = (a,b) => walls.some(c => cross(a, b, [c[0],c[1]], [c[2],c[3]]));
  const si = Math.floor((px-X0)/G), sj = Math.floor((py-Y0)/G);
  const seen = new Set([si+","+sj]); const q = [[si,sj]];
  while (q.length && seen.size < 3000) { const [i,j] = q.shift();
    for (const [di,dj] of [[1,0],[-1,0],[0,1],[0,-1]]) { const ni=i+di,nj=j+dj; if (ni<0||nj<0||ni>=COLS||nj>=ROWS) continue; const k=ni+","+nj; if (seen.has(k)) continue; if (blocked(centre(i,j),centre(ni,nj))) continue; seen.add(k); q.push([ni,nj]); } }
  return { square: [X0+si*G, Y0+sj*G], cell: [si,sj], component: seen.size, walls: walls.length };
};
