async function build(spec) {
  const src = await mm.getDocument(spec.mm);
  const data = src.toObject();
  delete data._id;
  data.name = spec.name;
  data.folder = folder.id;
  data.img = DR + spec.art + ".png";
  data._stats = foundry.utils.mergeObject(data._stats ?? {}, {compendiumSource: src.uuid});
  data.system.attributes.senses.ranges.darkvision = 120;
  data.system.traits.languages.value = spec.langs;
  data.system.details.type.subtype = "elf";
  data.system.details.biography.value = spec.bio + (data.system.details.biography.value ?? "");
  // items
  for (const it of data.items) { const f = spec.items[it.name]; if (f) f(it); }
  const dm = foundry.utils.deepClone(overlaySrc);
  dm[2].system.description.value = dm[2].system.description.value.replace("spell save DC 12", `spell save DC ${spec.drowDC}`);
  data.items.push(...dm, ...(spec.extra ?? []));
  data.flags = data.flags ?? {};
  data.flags["pentaryn-ties"] = { lore: lore(spec.lore) };
  const pt = data.prototypeToken;
  Object.assign(pt, { name: spec.name, width:1, height:1, actorLink: spec.linked, disposition: 0, lockRotation: true, displayName: 0 });
  pt.texture = foundry.utils.mergeObject(pt.texture ?? {}, { src: DR + spec.art + ".png", scaleX:1, scaleY:1, fit:"contain" });
  pt.ring = foundry.utils.mergeObject(pt.ring ?? {}, { enabled:true, colors:{ring:GREY, background:null}, subject:{scale:1, texture: RS + spec.subject} });
  pt.sight = foundry.utils.mergeObject(pt.sight ?? {}, { enabled:true, range:120, visionMode:"darkvision", angle:360 });
  pt.hidden = false;
  const a = await Actor.create(data);
  const links = [];
  for (const att of ["housebarrabin","nathryldhaun"]) links.push((await A.link(a, att)).ok);
  return { id:a.id, name:a.name, cr:a.system.details.cr, hp:a.system.attributes.hp.max, ac:a.system.attributes.ac.value, links, broken: A.broken ? A.broken(a) : "n/a" };
}

