const setTypes=(o,from,to)=>{for(const a of Object.values(o.system.activities??{}))for(const p of a.damage?.parts??[]){p.types=(p.types??[]).map(t=>t===from?to:t);}};
async function build(spec){
  const src=(await fromUuid(P+spec.block)).toObject();
  delete src._id; delete src.folder; src._stats={...(src._stats??{}),compendiumSource:null};
  src.name=spec.name; src.folder=folder.id; src.img=ART+spec.art+".png";
  for(const it of src.items){ spec.items?.(it); }
  src.items.push(...overlay(spec.overlay));
  for(const extra of spec.extra??[]) src.items.push(extra);
  src.system.attributes.senses.ranges.darkvision=120;
  src.system.traits.languages.value=spec.langs;
  src.system.details.biography.value=spec.bio;
  src.system.details.alignment="Neutral";
  src.prototypeToken=foundry.utils.mergeObject(src.prototypeToken,{name:spec.name,width:1,height:1,actorLink:spec.linked,disposition:0,lockRotation:true,displayName:0,
    texture:{src:ART+spec.art+".png",scaleX:1,scaleY:1},
    ring:{enabled:true,colors:{ring:spec.ring,background:null},effects:1,subject:{scale:1,texture:RS+spec.rs}},
    sight:{enabled:true,range:120}});
  src.flags={...(src.flags??{}),"pentaryn-ties":{lore:spec.lore}};
  const a=await Actor.create(src);
  const A=game.pentaryn.ties.attributes;
  for(const at of spec.attrs) await A.link(a,at);
  return a;
}
