  out.panelCats = spellBtn?.panel?.accordionPanelCategories?.length ?? spellBtn?.panel?._accordionPanelCategories?.length ?? null;
  const dom = spellBtn?.panel?.element?.querySelectorAll?.(".accordion-panel-category, .ech-accordion-panel-category")?.length;
  out.domCats = dom ?? null;
  out.otherBarsRituals = main.filter(p => p !== action).flatMap(p => p._buttons ?? []).filter(b => b.type === "spell").map(b => (b._spells ?? []).some(c => c.label === "Rituals (no slot)"));
} catch (e) { out.err = String(e); }
finally {
